/**
 * Unit tests for JacksonAnnotationIntrospector#findEnumValues
 */
public class JacksonAnnotationIntrospector_findEnumValues_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    // Test Enums for various scenarios

    enum TestEnumWithAnnotation {
        @JsonProperty("val_one")
        VAL_ONE,
        @JsonProperty("val_two")
        VAL_TWO,
        VAL_THREE // No annotation
    }

    enum TestEnumWithEmptyAnnotation {
        @JsonProperty("")
        EMPTY,
        @JsonProperty("valid")
        VALID
    }

    enum TestEnumNoAnnotation {
        A, B, C
    }

    @Test
    public void testFindEnumValues_WithAnnotations() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = {
            TestEnumWithAnnotation.VAL_ONE, 
            TestEnumWithAnnotation.VAL_TWO, 
            TestEnumWithAnnotation.VAL_THREE
        };
        String[] names = new String[enumValues.length];

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        // VAL_ONE should be "val_one"
        // VAL_TWO should be "val_two"
        // VAL_THREE should remain null (as per logic: if explValue != null, names[i] = explValue)
        assertEquals("val_one", result[0]);
        assertEquals("val_two", result[1]);
        assertEquals(null, result[2]);
    }

    @Test
    public void testFindEnumValues_WithEmptyAnnotationValue() {
        Class<?> enumType = TestEnumWithEmptyAnnotation.class;
        TestEnumWithEmptyAnnotation[] enumValues = {
            TestEnumWithEmptyAnnotation.EMPTY, 
            TestEnumWithEmptyAnnotation.VALID
        };
        String[] names = new String[enumValues.length];

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        // EMPTY has @JsonProperty(""), logic says: if (n.isEmpty()) continue;
        // VALID has @JsonProperty("valid")
        assertEquals(null, result[0]);
        assertEquals("valid", result[1]);
    }

    @Test
    public void testFindEnumValues_NoAnnotationsAtAll() {
        Class<?> enumType = TestEnumNoAnnotation.class;
        TestEnumNoAnnotation[] enumValues = {
            TestEnumNoAnnotation.A, 
            TestEnumNoAnnotation.B
        };
        String[] names = new String[enumValues.length];

        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        // expl will be null, loop over names won't execute
        assertEquals(null, result[0]);
        assertEquals(null, result[1]);
    }

    @Test
    public void testFindEnumValues_MixedExistingNames() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = {TestEnumWithAnnotation.VAL_ONE};

        // Test that it modifies the existing array provided
        String[] names = {"original"};
        String[] result = introspector.findEnumValues(enumType, enumValues, names);

        assertEquals("val_one", result[0]);
        assertEquals("val_one", names[0]); // Should be same object
    }

    @Test
    public void testFindEnumValues_EmptyInput() {
        Class<?> enumType = TestEnumWithAnnotation.class;
        TestEnumWithAnnotation[] enumValues = {};
        String[] names = {};

        String[] result = introspector.findEnumValues(enumType, enumValues, names);
        assertEquals(0, result.length);
    }

    /**
     * This dummy class is used to ensure we don't trigger errors if a non-enum 
     * class is passed, although the method expects an enumType.
     */
    static class NotAnEnum {
        @JsonProperty("field")
        public String field;
    }

    @Test
    public void testFindEnumValues_NonEnumClass() {
        Class<?> enumType = NotAnEnum.class;
        // Since findEnumValues iterates over fields and checks isEnumConstant()
        // A non-enum class will result in expl being null.
        Object[] enumValues = new Object[0];
        String[] names = new String[0];

        String[] result = introspector.findEnumValues(enumType, (Enum<?>[]) new Enum[0], names);
        assertEquals(0, result.length);
    }
}
